        struct CivicProbe {public uint health,damage,generation,flags;public float cooldown;public uint patrolIndex,lastHitTick,pad;public Vector4 body;}
        IEnumerator ValidateCivicSecurity(){var local=world.Base;var sim=local.Civilisation;var c=local.Settlements[0];foreach(var faction in sim.State.factions)faction.autonomous=false;sim.Settings.autoExtendSettlementRoads=false;world.Rig.InputEnabled=false;
            var hq=local.Buildings.Find(b=>b.team==0&&b.definition.id=="command");local.Factions[0].wallet.Credit(new ResourceCost{materials=10000});
            Check(local.TryConstructInfrastructure(CivilisationRuntime.PoliceHeadquarters,0),"Police HQ is a paid buildable service");var police=local.Buildings[local.Buildings.Count-1];police.construction=police.definition.time;police.WorkersAssigned=8;Check(local.Roads.ConnectToNetwork(police,hq,out _),"Police HQ connects to the existing road graph");
            Check(local.TryConstructInfrastructure(CivilisationRuntime.Graveyard,0),"Graveyard is a paid buildable service");var grave=local.Buildings[local.Buildings.Count-1];grave.construction=grave.definition.time;grave.WorkersAssigned=2;Check(local.Roads.ConnectToNetwork(grave,hq,out _),"Graveyard connects to the existing road graph");
            sim.Advance(1);police.WorkersAssigned=8;grave.WorkersAssigned=2;police.powered=grave.powered=true;
            var officer=c.residents[0];officer.role=CivilianRole.Officer;officer.servedPolice=true;officer.workplace=police.persistentId;sim.TickCivicServices(local,c);Check(c.security.patrolStops.Count>1,"Police default circuit visits connected residential entrances");
            sim.State.time=650;sim.Planet(world.definition.bodyId).lastSimulatedTime=650;local.Citizens.Step(.25f,true);var probes=new CivicProbe[local.Citizens.Count];local.Citizens.CivicStates.GetData(probes);Check(probes[0].health==100&&(probes[0].flags&2)!=0,$"Staffed police HQ assigns a GPU patrol officer (health {probes[0].health}, flags {probes[0].flags}, workplace {officer.workplace}, ready {CivilisationRuntime.CivicServiceReady(police)})");uint start=probes[0].patrolIndex;bool advanced=false;
            for(int i=0;i<1800;i++){local.Citizens.Step(.25f,true);if(i%60==0){local.Citizens.CivicStates.GetData(probes);advanced|=probes[0].patrolIndex!=start;yield return null;}}local.Citizens.CivicStates.GetData(probes);Check(advanced,"GPU patrol advances through its ordered road stops");var walkers=new Walker[local.Citizens.Count];local.Citizens.WalkerStatesForValidation.GetData(walkers);Check(walkers[0].initialised==1&&walkers[0].node<local.Roads.Nodes.Length,"GPU officer stays on the road network throughout its circuit");
            // Validation alone can inspect/write poses. Runtime combat never copies the army or live citizen state to CPU.
            var unit=new UnitState[1];world.UnitsForValidation.GetData(unit,0,0,1);var saved=unit[0];var zombie=saved;zombie.packed=2u|(31u<<8);zombie.flags=1;zombie.health=100;zombie.cooldown=0;zombie.target=uint.MaxValue;zombie.position=CubeSphere.Encode(((Vector3)probes[0].body).normalized);zombie.previous=zombie.position;world.UnitsForValidation.SetData(new[]{zombie},0,0,1);
            for(int i=0;i<95;i++){world.TickCivicCombatForValidation();if(i%10==0)yield return null;}world.UnitsForValidation.GetData(unit,0,0,1);Check(unit[0].health==0,"GPU officer encounters and kills an actual army zombie");
            int victimSlot=1;var victim=c.residents[victimSlot];probes[victimSlot].health=1;probes[victimSlot].flags=1;probes[victimSlot].body=probes[0].body;probes[0].flags=0;local.Citizens.CivicStates.SetData(probes);zombie.health=100;zombie.cooldown=0;world.UnitsForValidation.SetData(new[]{zombie},0,0,1);
            double deadline=Time.realtimeSinceStartupAsDouble+5;while(victim.alive&&Time.realtimeSinceStartupAsDouble<deadline){world.TickCivicCombatForValidation();yield return null;}
            Check(!victim.alive&&c.deaths.Exists(d=>d.resident==victim.id&&d.cause==DeathCause.ZombieAttack),"Zombie kills an outdoor citizen and bounded GPU event records the correct named death");world.UnitsForValidation.SetData(new[]{saved},0,0,1);
            var record=c.deaths.Find(d=>d.resident==victim.id);int population=c.population,deaths=c.deaths.Count;double credits=CivilisationRuntime.Credits(c);sim.RecordDeath(c,victim,DeathCause.ZombieAttack,999,Vector2.zero);Check(c.population==population&&c.deaths.Count==deaths&&Math.Abs(CivilisationRuntime.Credits(c)-credits)<.001,"Repeated death events neither duplicate deaths nor destroy inheritance");sim.TickCivicServices(local,c);Check(c.security.requestedPatrols>=3,"Civilian zombie deaths automatically raise requested patrol strength");
            var hearse=c.cargoVehicles.Find(v=>v.funeral);Check(hearse!=null&&hearse.phase==CargoVehiclePhase.Collecting,"A staffed graveyard dispatches its hearse for the recorded body");
            for(int i=0;i<4000&&!record.delivered;i++){local.CargoNavigation.Step(.25f,true);sim.TickCivicServices(local,c);if(i%60==0)yield return null;}Check(record.collected&&record.delivered,"Actual GPU hearse reaches the pickup and returns on roads before body delivery");
            var mortuary=c.installations.Find(i=>i.id==hearse.warehouse);mortuary.inventory.Deposit("construction_materials",160);double materials=mortuary.inventory.Get("construction_materials");Check(!sim.Logistics.UpgradeCarrier(local,0,hearse.id)&&mortuary.inventory.Get("construction_materials")==materials,"Hearses cannot consume materials on unsupported cargo upgrades");yield return ValidateHearseInspection(hearse,record);
            var policeDeath=sim.RecordDeath(c,officer,DeathCause.ZombieAttack,650,record.place);Check(policeDeath.policeHonours&&policeDeath.ceremonyDue==1200,"Fallen officers receive honours scheduled for the next day");sim.State.time=1200;sim.TickCivicServices(local,c);Check(policeDeath.ceremonyAt==0,"Police ceremony waits for actual body transport");
            for(int i=0;i<4000&&!policeDeath.delivered;i++){local.CargoNavigation.Step(.25f,true);sim.TickCivicServices(local,c);if(i%60==0)yield return null;}Check(policeDeath.delivered,"Police body is physically collected and delivered by the hearse");sim.State.time=1300;sim.TickCivicServices(local,c);Check(policeDeath.ceremonyAt>=1200,"Delivered police receive their next-day ceremony");sim.State.time=1400;sim.TickCivicServices(local,c);Check(policeDeath.interred,"Police honours conclude with burial");
            var elder=c.residents.Find(p=>p.alive);elder.age=101;c.lastCivicDay=2;sim.State.time=1800;sim.TickSociety(local,c,600);Check(!elder.alive&&c.deaths.Exists(d=>d.resident==elder.id&&d.cause==DeathCause.OldAge),"Old-age deaths enter the same named funeral and transport service");
            var copy=JsonUtility.FromJson<ColonyState>(JsonUtility.ToJson(c));Check(copy.deaths.Count==c.deaths.Count&&copy.deaths[0].name==record.name&&copy.cargoVehicles.Exists(v=>v.funeral),"Death dates, causes, patrol routes and hearse missions survive save serialization");Check(sim.CivicDate(650).Contains("day 2"),"Death records display the game calendar date");sim.State.time=2200;c.security.day=4;c.security.civilianDeathsToday=2;c.security.civilianDeathsYesterday=3;var late=c.residents.Find(p=>p.alive&&!p.servedPolice);sim.RecordDeath(c,late,DeathCause.ZombieAttack,2199.75,record.place);Check(c.security.day==4&&c.security.civilianDeathsToday==2&&c.security.civilianDeathsYesterday==4,"A delayed GPU death across midnight updates yesterday without erasing today's patrol statistics");
            Check(sim.CivicDate(400).Contains("day 2"),"The calendar date rolls over at local midnight");Check(sim.NextFuneralMorning(550)==1200,"A pre-dawn police death schedules honours for the following calendar day");ValidateDeathQueue();report.population=c.population;report.households=c.households.Count;report.flowBytes=local.Citizens.FlowStorageBytes;Check(report.runtimeErrors==0,"Civic combat, road transport and ceremonies emit no runtime errors");
        }
        struct CivicPose {public Vector4 position,right,up,forward,properties;}
        IEnumerator ValidateHearseInspection(CargoVehicleState hearse,DeathRecord record){var local=world.Base;var poses=new CivicPose[local.CargoNavigation.Count];local.CargoNavigation.Poses.GetData(poses);int slot=Array.FindIndex(poses,p=>p.properties.x==43);Check(slot>=0,"Hearse has a distinct GPU-rendered road vehicle pose");var pose=poses[slot];Vector3 up=((Vector3)pose.up).normalized;bool selected=false;local.CargoNavigation.PickHearse(new Ray(world.PlanetRenderCentre+(Vector3)pose.position+up*100,-up),v=>{selected=v.id==hearse.id;local.SelectHearse(v);});double until=Time.realtimeSinceStartupAsDouble+3;while(!selected&&Time.realtimeSinceStartupAsDouble<until)yield return null;Check(selected,"GPU ray selection identifies the actual hearse without CPU vehicle poses");
            for(int i=0;i<5;i++)yield return null;var root=world.Hud.Root;Check(root.Q<Label>("civic-hearse-title")!=null&&root.Q<Label>("civic-deceased-name")?.text.Contains(record.name)==true,"Selecting a hearse displays its deceased passenger biography");local.ClearSelection();
            var grave=local.FindBuilding(hearse.warehouse);world.Rig.SetFocusDirection(CubeSphere.Decode(grave.position));world.Rig.Distance=200;world.Rig.RefreshPose();local.Rebase();Physics.SyncTransforms();Check(local.Pick(world.View.WorldToScreenPoint(grave.visual.transform.position)),"The graveyard remains selectable through normal building picking");world.Hud.Tick();Check(root.Q<Label>("civic-death-register")!=null&&root.Q<Label>("civic-deceased-name")?.text.Contains(record.name)==true,"Graveyard inspection exposes recent named deaths to spectators");
        }
        struct QueueEvent {public uint slot,generation,cause,tick;public Vector4 body;}
        void ValidateDeathQueue(){var shader=Instantiate(Resources.Load<ComputeShader>("MassiveArmy/SettlementCitizens"));using(var states=new GraphicsBuffer(GraphicsBuffer.Target.Structured,300,48))using(var events=new GraphicsBuffer(GraphicsBuffer.Target.Structured,257,32))using(var ack=new GraphicsBuffer(GraphicsBuffer.Target.Structured,256,8)){
            var agents=new CivicProbe[300];for(int i=0;i<300;i++)agents[i].generation=1;states.SetData(agents);int drain=shader.FindKernel("DrainDeaths"),apply=shader.FindKernel("AcknowledgeDeaths");shader.SetInt("_WalkerCount",300);shader.SetBuffer(drain,"_CivicStates",states);shader.SetBuffer(drain,"_DeathEvents",events);events.SetData(new QueueEvent[1],0,0,1);shader.Dispatch(drain,3,1,1);var batch=new QueueEvent[257];events.GetData(batch);Check(batch[0].slot==300,"Burst deaths exceed the bounded queue without losing pending victims");
            var ids=new Vector2Int[256];for(int i=0;i<256;i++)ids[i]=new Vector2Int((int)batch[i+1].slot,1);ack.SetData(ids);shader.SetBuffer(apply,"_CivicStates",states);shader.SetBuffer(apply,"_Acknowledgements",ack);shader.SetInt("_AcknowledgementCount",256);shader.Dispatch(apply,2,1,1);events.SetData(new QueueEvent[1],0,0,1);shader.Dispatch(drain,3,1,1);events.GetData(batch);Check(batch[0].slot==44,"GPU queue retries the remaining 44 deaths after successful acknowledgement");
            states.GetData(agents);int slot=ids[0].x;agents[slot].generation=2;agents[slot].flags=0;states.SetData(agents);shader.Dispatch(apply,2,1,1);states.GetData(agents);Check((agents[slot].flags&4)==0,"A stale acknowledgement cannot erase a reused citizen slot");
        }Destroy(shader);}
    }
